import java.util.Scanner;

public class Main {
    static final int MOD_CONST = 1000000007;
    static int mod = MOD_CONST;
    static int[] P = new int[1000001];

    static int add(int i, int j) {
        int res = i + j;
        return res < mod ? res : res - mod;
    }

    static int mult(int i, int j) {
        return (int)((long) i * j % mod);
    }

    static int pwr(int i, int k) {
        int r = 1;
        while (k > 0) {
            if ((k & 1) == 1) {
                r = mult(r, i);
            }
            i = mult(i, i);
            k >>= 1;
        }
        return r;
    }

    static int beb(int a, int m) {
        for (int i = 0; i < P.length; i++) {
            P[i] = -1;
        }
        int s = (int) Math.sqrt(m);
        mod = m;
        int r = a % m;
        int d = pwr(a, m - 2);
        int i;
        for (i = 0; i <= s; ++i) {
            if (P[r] == -1) P[r] = i;
            r = mult(r, d);
            if (r == 1) {
                mod = MOD_CONST;
                return i + 1;
            }
        }
        d = pwr(a, s);
        r = d;
        for (i = 1; i <= s; ++i) {
            if (P[r] > -1) {
                mod = MOD_CONST;
                return s * i + P[r];
            }
            r = mult(r, d);
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        if (k == 1) {
            System.out.println(pwr(p, p));
        } else if (k == 0) {
            System.out.println(pwr(p, p - 1));
        } else {
            System.out.println(pwr(p, (p - 1) / beb(k, p)));
        }
        sc.close();
    }
}

